CREATE TYPE public.app_role AS ENUM ('admin','editor','spy','traffic');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_path text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.is_member() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()) $$;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (public.is_member() OR id=auth.uid());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.team_invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE CHECK(length(email)<=255), display_name text NOT NULL DEFAULT '', roles public.app_role[] NOT NULL, invited_by uuid NOT NULL REFERENCES public.profiles(id), accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.team_invitations TO authenticated; GRANT ALL ON public.team_invitations TO service_role;
ALTER TABLE public.team_invitations ENABLE ROW LEVEL SECURITY;
CREATE POLICY invitations_admin ON public.team_invitations FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.on_dr_user_created() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(new.id,coalesce((SELECT display_name FROM public.team_invitations WHERE lower(email)=lower(new.email)),'')); RETURN new; END $$;
CREATE TRIGGER dr_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.on_dr_user_created();
CREATE FUNCTION public.accept_team_invitation() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE invite public.team_invitations; verified_email text; BEGIN SELECT email INTO verified_email FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL; IF verified_email IS NULL THEN RAISE EXCEPTION 'Confirme seu e-mail para continuar'; END IF; SELECT * INTO invite FROM public.team_invitations WHERE lower(email)=lower(verified_email) AND accepted_at IS NULL FOR UPDATE; IF invite.id IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) SELECT auth.uid(),unnest(invite.roles) ON CONFLICT DO NOTHING; UPDATE public.team_invitations SET accepted_at=now() WHERE id=invite.id; END IF; END $$;
REVOKE ALL ON FUNCTION public.accept_team_invitation() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.accept_team_invitation() TO authenticated;
CREATE TABLE public.offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 160), product_name text NOT NULL DEFAULT '', niche text NOT NULL DEFAULT '', country text NOT NULL DEFAULT 'Brasil', language text NOT NULL DEFAULT 'Português', currency text NOT NULL DEFAULT 'BRL' CHECK(currency IN ('USD','BRL','MXN','ARS','ZAR')), sale_price numeric NOT NULL DEFAULT 0 CHECK(sale_price>=0), product_type text NOT NULL DEFAULT 'digital' CHECK(product_type IN ('digital','physical')), payment_model text NOT NULL DEFAULT '', sales_url text NOT NULL DEFAULT '', checkout_url text NOT NULL DEFAULT '', whatsapp_url text NOT NULL DEFAULT '', start_date date, responsible_id uuid REFERENCES public.profiles(id), description text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Ideia' CHECK(status IN ('Ideia','Em preparação','Em teste','Validou','Escalando','Pausada','Não validou','Encerrada')), archived boolean NOT NULL DEFAULT false, created_by uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.offers TO authenticated; GRANT ALL ON public.offers TO service_role;
ALTER TABLE public.offers ENABLE ROW LEVEL SECURITY;
CREATE POLICY offers_read ON public.offers FOR SELECT TO authenticated USING(public.is_member());
CREATE POLICY offers_create ON public.offers FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') AND created_by=auth.uid());
CREATE POLICY offers_update ON public.offers FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.demands (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200), offer_id uuid NOT NULL REFERENCES public.offers(id), kind text NOT NULL CHECK(kind IN ('individual','batch')), briefing text NOT NULL DEFAULT '', priority text NOT NULL DEFAULT 'Média' CHECK(priority IN ('Baixa','Média','Alta','Urgente')), due_date date, created_by uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), archived boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE ON public.demands TO authenticated; GRANT ALL ON public.demands TO service_role;
ALTER TABLE public.demands ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.demand_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), demand_id uuid NOT NULL REFERENCES public.demands(id), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), item_number integer NOT NULL CHECK(item_number>0), assigned_to uuid REFERENCES public.profiles(id), hook text NOT NULL DEFAULT '', copy text NOT NULL DEFAULT '', instructions text NOT NULL DEFAULT '', format text NOT NULL DEFAULT '9:16', language text NOT NULL DEFAULT 'Português', due_date date, status text NOT NULL DEFAULT 'Pendente' CHECK(status IN ('Pendente','Em edição','Aguardando aprovação','Ajustes solicitados','Aprovado','Cancelado')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(demand_id,item_number));
GRANT SELECT,INSERT,UPDATE ON public.demand_items TO authenticated; GRANT ALL ON public.demand_items TO service_role;
ALTER TABLE public.demand_items ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_read_demand(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.demand_items WHERE demand_id=_id AND assigned_to=auth.uid()) $$;
CREATE POLICY demands_read ON public.demands FOR SELECT TO authenticated USING(public.can_read_demand(id));
CREATE POLICY demands_insert ON public.demands FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') AND created_by=auth.uid());
CREATE POLICY demands_update ON public.demands FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY items_read ON public.demand_items FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR assigned_to=auth.uid());
CREATE POLICY items_insert ON public.demand_items FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY items_update ON public.demand_items FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR (assigned_to=auth.uid() AND public.has_role(auth.uid(),'editor'))) WITH CHECK(public.has_role(auth.uid(),'admin') OR (assigned_to=auth.uid() AND public.has_role(auth.uid(),'editor')));
CREATE TABLE public.files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), offer_id uuid REFERENCES public.offers(id), demand_id uuid REFERENCES public.demands(id), item_id uuid REFERENCES public.demand_items(id), path text NOT NULL UNIQUE, name text NOT NULL, mime_type text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes>0 AND size_bytes<=20971520), purpose text NOT NULL CHECK(purpose IN ('reference','final','product')), uploaded_by uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), CHECK(num_nonnulls(offer_id,demand_id,item_id)=1));
GRANT SELECT,INSERT,DELETE ON public.files TO authenticated; GRANT ALL ON public.files TO service_role;
ALTER TABLE public.files ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_access_file(_offer uuid,_demand uuid,_item uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR (_offer IS NOT NULL AND public.is_member()) OR (_demand IS NOT NULL AND public.can_read_demand(_demand)) OR EXISTS(SELECT 1 FROM public.demand_items WHERE id=_item AND assigned_to=auth.uid()) $$;
CREATE POLICY files_read ON public.files FOR SELECT TO authenticated USING(public.can_access_file(offer_id,demand_id,item_id));
CREATE POLICY files_insert ON public.files FOR INSERT TO authenticated WITH CHECK(uploaded_by=auth.uid() AND (public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'editor') AND item_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.demand_items WHERE id=item_id AND assigned_to=auth.uid()))));
CREATE POLICY files_cleanup ON public.files FOR DELETE TO authenticated USING(uploaded_by=auth.uid() AND NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='dr-files' AND name=path));
CREATE TABLE public.creative_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL REFERENCES public.demand_items(id), file_id uuid NOT NULL REFERENCES public.files(id), version integer NOT NULL CHECK(version>0), created_by uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(item_id,version));
GRANT SELECT,INSERT ON public.creative_versions TO authenticated; GRANT ALL ON public.creative_versions TO service_role;
ALTER TABLE public.creative_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY versions_read ON public.creative_versions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.demand_items WHERE id=item_id AND assigned_to=auth.uid()));
CREATE POLICY versions_insert ON public.creative_versions FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND (public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'editor') AND EXISTS(SELECT 1 FROM public.demand_items WHERE id=item_id AND assigned_to=auth.uid()))) AND EXISTS(SELECT 1 FROM public.files f JOIN storage.objects o ON o.name=f.path AND o.bucket_id='dr-files' WHERE f.id=file_id AND f.item_id=creative_versions.item_id AND f.purpose='final'));
CREATE FUNCTION public.validate_item_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN IF (to_jsonb(new)-'status') IS DISTINCT FROM (to_jsonb(old)-'status') THEN RAISE EXCEPTION 'Você só pode alterar o andamento de seus itens'; END IF; IF new.status NOT IN ('Em edição','Aguardando aprovação') THEN RAISE EXCEPTION 'Status não permitido para editor'; END IF; END IF; IF new.status='Aguardando aprovação' AND NOT EXISTS(SELECT 1 FROM public.creative_versions WHERE item_id=new.id) THEN RAISE EXCEPTION 'Anexe um arquivo final antes de enviar para aprovação'; END IF; RETURN new; END $$;
CREATE TRIGGER validate_demand_item_update BEFORE UPDATE ON public.demand_items FOR EACH ROW EXECUTE FUNCTION public.validate_item_update();
CREATE TABLE public.item_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_id uuid NOT NULL REFERENCES public.demand_items(id), author_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), body text NOT NULL CHECK(length(body) BETWEEN 1 AND 3000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.item_comments TO authenticated; GRANT ALL ON public.item_comments TO service_role;
ALTER TABLE public.item_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY comments_read ON public.item_comments FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.demand_items WHERE id=item_id AND assigned_to=auth.uid()));
CREATE POLICY comments_insert ON public.item_comments FOR INSERT TO authenticated WITH CHECK(author_id=auth.uid() AND (public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.demand_items WHERE id=item_id AND assigned_to=auth.uid())));
CREATE TABLE public.activity_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES public.profiles(id), entity_type text NOT NULL, entity_id uuid NOT NULL, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.activity_log TO authenticated; GRANT ALL ON public.activity_log TO service_role;
ALTER TABLE public.activity_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY activity_admin ON public.activity_log FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.log_dr_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.activity_log(actor_id,entity_type,entity_id,action) VALUES(auth.uid(),TG_TABLE_NAME,new.id,TG_OP); RETURN new; END $$;
CREATE TRIGGER offers_audit AFTER INSERT OR UPDATE ON public.offers FOR EACH ROW EXECUTE FUNCTION public.log_dr_change();
CREATE TRIGGER demands_audit AFTER INSERT OR UPDATE ON public.demands FOR EACH ROW EXECUTE FUNCTION public.log_dr_change();
CREATE TRIGGER items_audit AFTER INSERT OR UPDATE ON public.demand_items FOR EACH ROW EXECUTE FUNCTION public.log_dr_change();
CREATE INDEX demand_items_assignee ON public.demand_items(assigned_to,status);
CREATE INDEX demands_offer ON public.demands(offer_id);
CREATE INDEX files_item ON public.files(item_id); CREATE INDEX files_demand ON public.files(demand_id); CREATE INDEX files_offer ON public.files(offer_id);
CREATE INDEX versions_item ON public.creative_versions(item_id);
CREATE POLICY dr_storage_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='dr-files' AND EXISTS(SELECT 1 FROM public.files f WHERE f.path=name AND public.can_access_file(f.offer_id,f.demand_id,f.item_id)));
CREATE POLICY dr_storage_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='dr-files' AND EXISTS(SELECT 1 FROM public.files f WHERE f.path=name AND f.uploaded_by=auth.uid() AND (public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'editor') AND f.item_id IS NOT NULL AND public.can_access_file(NULL,NULL,f.item_id)))));
CREATE FUNCTION public.create_demand(payload jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE demand_uuid uuid; item jsonb; n integer:=0; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Apenas administradores podem criar demandas'; END IF; IF jsonb_array_length(payload->'items')<1 OR jsonb_array_length(payload->'items')>100 THEN RAISE EXCEPTION 'Informe entre 1 e 100 criativos'; END IF; IF payload->>'kind'='individual' AND jsonb_array_length(payload->'items')<>1 THEN RAISE EXCEPTION 'Uma demanda individual deve conter um criativo'; END IF; INSERT INTO public.demands(title,offer_id,kind,briefing,priority,due_date) VALUES(payload->>'title',(payload->>'offer_id')::uuid,payload->>'kind',coalesce(payload->>'briefing',''),payload->>'priority',nullif(payload->>'due_date','')::date) RETURNING id INTO demand_uuid; FOR item IN SELECT * FROM jsonb_array_elements(payload->'items') LOOP n:=n+1; INSERT INTO public.demand_items(demand_id,name,item_number,assigned_to,hook,copy,instructions,format,language,due_date) VALUES(demand_uuid,item->>'name',n,nullif(item->>'assigned_to','')::uuid,coalesce(item->>'hook',''),coalesce(item->>'copy',''),coalesce(item->>'instructions',''),coalesce(item->>'format','9:16'),coalesce(item->>'language','Português'),nullif(item->>'due_date','')::date); END LOOP; RETURN demand_uuid; END $$;
REVOKE ALL ON FUNCTION public.create_demand(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_demand(jsonb) TO authenticated;